// lru_cache.hpp
#pragma once

#include <cstddef>
#include <deque>
#include <optional>
#include <unordered_map>
#include <mutex>

template <typename K, typename V>
class LRUCache {
private:
    struct Node {
        K key;
        V value;
    };

    std::size_t capacity_;
    std::deque<Node> deque_;
    std::unordered_map<K, typename std::deque<Node>::iterator> map_;

    void make_recent(typename std::deque<Node>::iterator it) {
        deque_.splice(deque_.begin(), deque_, it);
    }

public:
    explicit LRUCache(std::size_t capacity) : capacity_(capacity) {}

    std::optional<V> get(const K& key) const {
        std::lock_guard<std::mutex> lock(mutex_); // C++17 guard
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::optional<V>{};
        }
        make_recent(it->second);
        return std::optional<V>(it->second->value);
    }

    void put(const K& key, const V& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->value = value;
            make_recent(it->second);
            return;
        }

        if (capacity_ == 0) {
            return;
        }

        if (map_.size() == capacity_) {
            const Node& back = deque_.back();
            map_.erase(back.key);
            deque_.pop_back();
        }

        deque_.push_front({key, value});
        map_.emplace(key, deque_.begin());
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return map_.size();
    }

private:
    mutable std::mutex mutex_;
};
