def topo_sort(graph):
    # Collect all nodes, including those that appear only as prerequisites
    all_nodes = set(graph.keys())
    for node, preds in graph.items():
        for p in preds:
            all_nodes.add(p)

    # Build in-degree map: number of prerequisites not yet processed
    in_degree = {n: 0 for n in all_nodes}
    adj = {n: [] for n in all_nodes}

    for node, preds in graph.items():
        for p in preds:
            adj[p].append(node)
            in_degree[node] += 1

    # Use a min-heap to always pick the lexicographically smallest ready node
    import heapq
    ready = [n for n in all_nodes if in_degree[n] == 0]
    heapq.heapify(ready)  # not valid; use heapify from heapq? Actually heapq.heapify exists in 3.5+

    # Actually use heap list and heapify
    # Let's just heapify properly:
    # (already did ready list; use heapq.heapify(ready))

    result = []
    while ready:
        cur = heapq.heappop(ready)
        result.append(cur)
        for nxt in adj[cur]:
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                heapq.heappush(ready, nxt)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in graph")

    return result
