import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.time.LocalDate;

public class Library {

    private final Map<String, Book> books = new HashMap<String, Book>();
    private final Map<String, String> borrowedBy = new HashMap<String, String>();

    public class Book {
        public final String isbn;
        public final String title;
        public String borrower;
        public LocalDate borrowDate;

        public Book(String isbn, String title) {
            this.isbn = isbn;
            this.title = title;
            this.borrower = null;
            this.borrowDate = null;
        }

        public boolean isBorrowed() {
            return this.borrower != null;
        }
    }

    public void addBook(String isbn, String title) {
        if (isbn == null) {
            throw new IllegalArgumentException("isbn cannot be null");
        }
        if (books.containsKey(isbn)) {
            throw new IllegalArgumentException("book with isbn " + isbn + " already exists");
        }
        books.put(isbn, new Book(isbn, title));
    }

    public void borrow(String isbn, String member, LocalDate date) {
        if (!books.containsKey(isbn)) {
            throw new NoSuchElementException("unknown isbn: " + isbn);
        }
        Book book = books.get(isbn);
        if (book.isBorrowed()) {
            throw new IllegalStateException("book " + isbn + " is already borrowed");
        }
        book.borrower = member;
        book.borrowDate = date;
        borrowedBy.put(isbn, member);
    }

    public void giveBack(String isbn) {
        if (!books.containsKey(isbn)) {
            throw new NoSuchElementException("unknown isbn: " + isbn);
        }
        Book book = books.get(isbn);
        if (!book.isBorrowed()) {
            throw new IllegalStateException("book " + isbn + " is not borrowed");
        }
        book.borrower = null;
        book.borrowDate = null;
        borrowedBy.remove(isbn);
    }

    public List<String> overdue(LocalDate today, int days) {
        List<String> result = new ArrayList<String>();
        for (Book book : books.values()) {
            if (book.isBorrowed() && book.borrowDate != null) {
                int duration = today.compareTo(book.borrowDate);
                if (duration > days) {
                    result.add(book.title);
                }
            }
        }
        result.sort();
        return result;
    }

    public Map<String, Integer> loansByMember() {
        Map<String, Integer> counts = new HashMap<String, Integer>();
        for (String isbn : borrowedBy.keySet()) {
            String member = borrowedBy.get(isbn);
            counts[member] = (counts.containsKey(member) ? counts.get(member) : 0) + 1;
        }
        return counts;
    }

    public class NoSuchElementException extends java.lang.Exception {
        public NoSuchElementException(String message) {
            super(message);
        }
    }

    public class IllegalStateException extends java.lang.Exception {
        public IllegalStateException(String message) {
            super(message);
        }
    }
}
